 1 | // SPDX-License-Identifier: UNLICENSED
 2 | pragma solidity ^0.8.15;
 3 | 
 4 | import {IERC20, SafeERC20} from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
 5 | import {Quest} from './Quest.sol';
 6 | import {QuestFactory} from './QuestFactory.sol';
 7 | 
 8 | /// @title Erc20Quest
 9 | /// @author RabbitHole.gg
10 | /// @notice This contract is used to create a quest that rewards ERC20 tokens.
11 | contract Erc20Quest is Quest {
12 |     using SafeERC20 for IERC20;
13 |     uint256 public immutable questFee;
14 |     address public immutable protocolFeeRecipient;
15 |     QuestFactory public immutable questFactoryContract;
16 | 
17 |     constructor(
18 |         address rewardTokenAddress_,
19 |         uint256 endTime_,
20 |         uint256 startTime_,
21 |         uint256 totalParticipants_,
22 |         uint256 rewardAmountInWeiOrTokenId_,
23 |         string memory questId_,
24 |         address receiptContractAddress_,
25 |         uint256 questFee_,
26 |         address protocolFeeRecipient_
27 |     )
28 |         Quest(
29 |             rewardTokenAddress_,
30 |             endTime_,
31 |             startTime_,
32 |             totalParticipants_,
33 |             rewardAmountInWeiOrTokenId_,
34 |             questId_,
35 |             receiptContractAddress_
36 |         )
37 |     {
38 |         questFee = questFee_;
39 |         protocolFeeRecipient = protocolFeeRecipient_;
40 |         questFactoryContract = QuestFactory(msg.sender);
41 |     }
42 | 
43 |     /// @dev Function that gets the maximum amount of rewards that can be claimed by all users. It does not include the protocol fee
44 |     /// @return The maximum amount of rewards that can be claimed by all users
45 |     function maxTotalRewards() public view returns (uint256) {
46 |         return totalParticipants * rewardAmountInWeiOrTokenId;
47 |     }
48 | 
49 |     /// @notice Function that gets the maximum amount of rewards that can be claimed by the protocol or the quest deployer
50 |     /// @dev The 10_000 comes from Basis Points: https://www.investopedia.com/terms/b/basispoint.asp
51 |     /// @return The maximum amount of rewards that can be claimed by the protocol or the quest deployer
52 |     function maxProtocolReward() public view returns (uint256) {
53 |         return (maxTotalRewards() * questFee) / 10_000;
54 |     }

 55 |     /// @notice Pauses the Quest
 56 |     /// @dev Only the owner of the Quest can call this function. Also requires that the Quest has started (not by date, but by calling the start function)
 57 |     function pause() public onlyOwner onlyStarted {
 58 |         isPaused = true;
 59 |     }
 60 | 
 61 |     /// @notice Unpauses the Quest
 62 |     /// @dev Only the owner of the Quest can call this function. Also requires that the Quest has started (not by date, but by calling the start function)
 63 |     function unPause() public onlyOwner onlyStarted {
 64 |         isPaused = false;
 65 |     }
 66 | 
 67 |     /// @notice Marks token ids as claimed
 68 |     /// @param tokenIds_ The token ids to mark as claimed
 69 |     function _setClaimed(uint256[] memory tokenIds_) private {
 70 |         for (uint i = 0; i < tokenIds_.length; i++) {
 71 |             claimedList[tokenIds_[i]] = true;
 72 |         }
 73 |     }
 74 | 
 75 |     /// @notice Prevents reward withdrawal until the Quest has ended
 76 |     modifier onlyAdminWithdrawAfterEnd() {
 77 |         if (block.timestamp < endTime) revert NoWithdrawDuringClaim();
 78 |         _;
 79 |     }
 80 | 
 81 |     /// @notice Checks if the Quest has started at the function level
 82 |     modifier onlyStarted() {
 83 |         if (!hasStarted) revert NotStarted();
 84 |         _;
 85 |     }
 86 | 
 87 |     /// @notice Checks if quest has started both at the function level and at the start time
 88 |     modifier onlyQuestActive() {
 89 |         if (!hasStarted) revert NotStarted();
 90 |         if (block.timestamp < startTime) revert ClaimWindowNotStarted();
 91 |         _;
 92 |     }
 93 | 
 94 |     /// @notice Allows user to claim the rewards entitled to them
 95 |     /// @dev User can claim based on the (unclaimed) number of tokens they own of the Quest
 96 |     function claim() public virtual onlyQuestActive {
 97 |         if (isPaused) revert QuestPaused();
 98 | 
 99 |         uint[] memory tokens = rabbitHoleReceiptContract.getOwnedTokenIdsOfQuest(questId, msg.sender);
100 | 
101 |         if (tokens.length == 0) revert NoTokensToClaim();
102 | 
103 |         uint256 redeemableTokenCount = 0;
104 |         for (uint i = 0; i < tokens.length; i++) {
105 |             if (!isClaimed(tokens[i])) {
106 |                 redeemableTokenCount++;
107 |             }
108 |         }
109 | 
110 |         if (redeemableTokenCount == 0) revert AlreadyClaimed();
111 | 
112 |         uint256 totalRedeemableRewards = _calculateRewards(redeemableTokenCount);
113 |         _setClaimed(tokens);
114 |         _transferRewards(totalRedeemableRewards);
115 |         redeemedTokens += redeemableTokenCount;
